-- v_role_menu_button_detail view
CREATE ALGORITHM=UNDEFINED DEFINER=`dawn`@`%` SQL SECURITY DEFINER VIEW `v_role_menu_button_detail` AS select `rmb`.`id` AS `id`,`rmb`.`role_id` AS `role_id`,`rmb`.`menu_id` AS `menu_id`,`rmb`.`button_id` AS `button_id`,`rmb`.`create_time` AS `create_time`,`r`.`role_name` AS `role_name`,`r`.`role_code` AS `role_code`,`r`.`enabled` AS `role_enabled`,`m`.`name` AS `menu_name`,`m`.`path` AS `menu_path`,`m`.`title` AS `menu_title`,`m`.`icon` AS `menu_icon`,`m`.`component` AS `menu_component`,`m`.`status` AS `menu_status`,`mb`.`title` AS `button_title`,`mb`.`auth_mark` AS `button_auth_mark`,`mb`.`sort_order` AS `button_sort_order` from (((`role_menu_buttons` `rmb` join `roles` `r` on((`rmb`.`role_id` = `r`.`role_id`))) join `menus` `m` on((`rmb`.`menu_id` = `m`.`id`))) join `menu_buttons` `mb` on((`rmb`.`button_id` = `mb`.`id`))) order by `rmb`.`role_id`,`rmb`.`menu_id`,`mb`.`sort_order`;